-- Reviewed senior batch 010; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3531,"word":"illuminate","meaning":"照亮","example":"The small lamp helped illuminate the map inside the dark cabin.","example_zh":"小燈幫忙照亮昏暗木屋裡的地圖。","original_meaning":"照亮","original_example":"The lamp will illuminate the room.","original_example_zh":"這盞燈將照亮房間。"},{"source_id":3532,"word":"illiterate","meaning":"文盲的；不識字的","example":"The volunteer patiently helped an illiterate adult learn to read.","example_zh":"志工耐心幫助不識字的成年人學習閱讀。","original_meaning":"文盲的","original_example":"He cannot read or write because he is illiterate.","original_example_zh":"他因為不識字而無法讀寫。"},{"source_id":3533,"word":"immerse","meaning":"沈浸","example":"We could immerse ourselves in music during the quiet rehearsal.","example_zh":"安靜排練時，我們能沉浸在音樂裡。","original_meaning":"沈浸","original_example":"She likes to immerse herself in books.","original_example_zh":"她喜歡沉浸在書本中。"},{"source_id":3534,"word":"immigration","meaning":"移民","example":"The museum traced the history of immigration to the port city.","example_zh":"博物館追溯移民來到這座港都的歷史。","original_meaning":"移民","original_example":"Immigration policies affect many families.","original_example_zh":"移民政策影響許多家庭。"},{"source_id":3535,"word":"immortal","meaning":"不朽的","example":"The poet's immortal stories were read by many generations.","example_zh":"那位詩人不朽的故事，流傳給許多世代閱讀。","original_meaning":"不朽的","original_example":"Legends say the hero became immortal.","original_example_zh":"傳說中，那位英雄變得不朽。"},{"source_id":3536,"word":"immunity","meaning":"免疫","example":"The science model showed how immunity helps the body resist disease.","example_zh":"科學模型展示免疫如何幫助身體抵抗疾病。","original_meaning":"免疫","original_example":"Vaccines help build immunity.","original_example_zh":"疫苗有助於建立免疫力。"},{"source_id":3537,"word":"impartial","meaning":"公正的","example":"The impartial judge listened carefully to both teams.","example_zh":"公正的評審仔細聆聽兩隊的說明。","original_meaning":"公正的","original_example":"A judge must remain impartial.","original_example_zh":"法官必須保持公正。"},{"source_id":3538,"word":"impasse","meaning":"僵局","example":"The clubs reached an impasse over how to share the rehearsal room.","example_zh":"兩個社團在如何共用排練室的問題上陷入僵局。","original_meaning":"僵局","original_example":"The negotiations reached an impasse.","original_example_zh":"談判陷入僵局。"},{"source_id":3539,"word":"impeach","meaning":"彈劾","example":"The history class learned why lawmakers voted to impeach an official.","example_zh":"歷史課學習議員為何投票彈劾一位官員。","original_meaning":"彈劾","original_example":"The official was impeached for corruption.","original_example_zh":"該官員因貪腐遭彈劾。"},{"source_id":3540,"word":"impediment","meaning":"障礙","example":"The fallen branch was an impediment to carrying the cart uphill.","example_zh":"倒枝妨礙我們把推車往坡上推。","original_meaning":"障礙","original_example":"Poor planning is a major impediment.","original_example_zh":"規劃不周是主要障礙。"},{"source_id":3541,"word":"imperialism","meaning":"帝國主義","example":"The exhibit examined how imperialism expanded control over distant territories.","example_zh":"展覽探討帝國主義如何把控制擴展到遠方領土。","original_meaning":"帝國主義","original_example":"Imperialism shaped world history.","original_example_zh":"帝國主義塑造了世界歷史。"},{"source_id":3542,"word":"impetus","meaning":"動力","example":"The successful first concert gave the orchestra fresh impetus.","example_zh":"第一場音樂會成功，給管弦樂團帶來新的動力。","original_meaning":"動力","original_example":"His speech gave new impetus to the movement.","original_example_zh":"他的演說為運動注入了新動力。"},{"source_id":3543,"word":"implausible","meaning":"不合理的","example":"The claim that the tiny toy could lift a bicycle seemed implausible.","example_zh":"說小玩具能舉起腳踏車，聽起來不太合理。","original_meaning":"不合理的","original_example":"His explanation sounded implausible.","original_example_zh":"他的解釋聽起來難以置信。"},{"source_id":3544,"word":"imposition","meaning":"強加","example":"The extra cleaning duty felt like an unfair imposition on one student.","example_zh":"把額外打掃工作全交給一人，讓那位學生覺得遭到不公平強加。","original_meaning":"強加","original_example":"The new law was seen as an imposition.","original_example_zh":"新法律被視為一種強加。"},{"source_id":3545,"word":"impoverish","meaning":"使貧窮","example":"Years of crop failure can impoverish a farming community.","example_zh":"連年收成不佳，可能使農業社區陷入貧困。","original_meaning":"使貧窮","original_example":"War can impoverish entire regions.","original_example_zh":"戰爭可能使整個地區陷入貧困。"},{"source_id":3546,"word":"imprisonment","meaning":"監禁","example":"The novel followed an innocent man's long imprisonment.","example_zh":"小說描寫一位無辜男子漫長的監禁生活。","original_meaning":"監禁","original_example":"He faced imprisonment for his crimes.","original_example_zh":"他因犯罪行為面臨監禁。"},{"source_id":3547,"word":"inadequate","meaning":"不足的","example":"The tiny box was inadequate for the growing tree's roots.","example_zh":"小箱子容不下持續生長的樹根。","original_meaning":"不足的","original_example":"The resources are inadequate for the task.","original_example_zh":"現有資源不足以應付這項任務。"},{"source_id":3548,"word":"inaugurate","meaning":"就任","example":"The new president will be inaugurated at a formal ceremony.","example_zh":"新任總統將在正式典禮上宣誓就職。","original_meaning":"就任","original_example":"The president will inaugurate the event.","original_example_zh":"總統將為該活動主持開幕儀式。"},{"source_id":3549,"word":"incarcerate","meaning":"監禁","example":"The court decided to incarcerate the convicted thief.","example_zh":"法院決定監禁已定罪的竊賊。","original_meaning":"監禁","original_example":"The police decided to incarcerate the suspect.","original_example_zh":"警方決定將該名嫌疑人收押。"},{"source_id":3550,"word":"inception","meaning":"開始","example":"Students helped design the garden from the project's inception.","example_zh":"學生從計畫一開始就參與花園設計。","original_meaning":"開始","original_example":"The project marked the inception of a new era.","original_example_zh":"該計畫標誌著新時代的開端。"},{"source_id":3551,"word":"incidental","meaning":"偶發的；附帶的","example":"The birdsong was an incidental part of our rehearsal in the garden.","example_zh":"鳥鳴是我們在花園排練時的附帶聲音。","original_meaning":"偶發的","original_example":"There were incidental costs involved.","original_example_zh":"涉及一些附帶費用。"},{"source_id":3552,"word":"inclusive","meaning":"包容的","example":"The inclusive art club welcomed students with many different abilities.","example_zh":"這個包容的美術社歡迎能力各異的學生。","original_meaning":"包容的","original_example":"The policy is inclusive of all groups.","original_example_zh":"這項政策涵蓋所有群體。"},{"source_id":3553,"word":"incompatible","meaning":"不相容的","example":"The new plug was incompatible with the old classroom socket.","example_zh":"新插頭與教室的舊插座不相容。","original_meaning":"不相容的","original_example":"The two systems are incompatible.","original_example_zh":"這兩種系統不相容。"},{"source_id":3554,"word":"increment","meaning":"增量","example":"We added a small increment of weight before testing the bridge again.","example_zh":"我們增加一小份重量，再次測試橋梁。","original_meaning":"增量","original_example":"The salary will increase in small increments.","original_example_zh":"薪資將以小幅幅度調升。"},{"source_id":3555,"word":"incur","meaning":"招致","example":"A broken wheel caused the club to incur extra repair costs.","example_zh":"輪子壞掉，讓社團多出維修費用。","original_meaning":"招致","original_example":"You may incur extra charges.","original_example_zh":"您可能會產生額外費用。"},{"source_id":3556,"word":"indignation","meaning":"憤慨","example":"The students expressed indignation when the old tree was damaged.","example_zh":"老樹遭破壞時，學生表達了憤慨。","original_meaning":"憤慨","original_example":"He reacted with indignation to the insult.","original_example_zh":"他對這項侮辱感到憤慨。"},{"source_id":3557,"word":"indoctrinate","meaning":"灌輸","example":"The novel showed a ruler trying to indoctrinate citizens into blind obedience.","example_zh":"小說呈現統治者試圖灌輸人民盲目服從的觀念。","original_meaning":"灌輸","original_example":"They tried to indoctrinate the children.","original_example_zh":"他們試圖對孩子進行思想灌輸。"},{"source_id":3558,"word":"industrialize","meaning":"工業化","example":"The exhibit showed how new factories helped industrialize the region.","example_zh":"展覽呈現新工廠如何使該地區工業化。","original_meaning":"工業化","original_example":"The country began to industrialize rapidly.","original_example_zh":"該國開始迅速工業化。"},{"source_id":3559,"word":"inequality","meaning":"不平等","example":"The display revealed inequality in access to clean drinking water.","example_zh":"展示揭示取得乾淨飲水機會的不平等。","original_meaning":"不平等","original_example":"Economic inequality is a serious issue.","original_example_zh":"經濟不平等是一個嚴重的問題。"},{"source_id":3560,"word":"infer","meaning":"推論","example":"From the wet ground, we could infer that rain had fallen overnight.","example_zh":"從濕地面，我們能推論昨夜下過雨。","original_meaning":"推論","original_example":"We can infer meaning from context.","original_example_zh":"我們可以從上下文推斷意思。"},{"source_id":3561,"word":"infiltrate","meaning":"滲透","example":"Rainwater can infiltrate the soil through small cracks.","example_zh":"雨水能從小裂縫滲入土壤。","original_meaning":"滲透","original_example":"Spies attempted to infiltrate the organization.","original_example_zh":"間諜企圖滲透該組織。"},{"source_id":3562,"word":"inflict","meaning":"施加","example":"The storm can inflict serious damage on the wooden pier.","example_zh":"暴風雨可能使木碼頭嚴重受損。","original_meaning":"施加","original_example":"The storm will inflict serious damage.","original_example_zh":"風暴將造成嚴重破壞。"},{"source_id":3563,"word":"infringe","meaning":"侵犯","example":"Please do not infringe on another person's privacy by opening their letters.","example_zh":"請不要拆開別人的信，侵犯對方隱私。","original_meaning":"侵犯","original_example":"This rule may infringe on your rights.","original_example_zh":"這項規定可能侵犯您的權利。"},{"source_id":3564,"word":"ingenious","meaning":"巧妙的","example":"The ingenious watering device used a bottle and a simple tube.","example_zh":"巧妙的澆水裝置使用一個瓶子與簡單管子。","original_meaning":"巧妙的","original_example":"She found an ingenious solution.","original_example_zh":"她想出了個絕妙的解決方案。"},{"source_id":3565,"word":"ingredient","meaning":"成分","example":"Flour was the main ingredient in the bread we baked.","example_zh":"麵粉是我們烤麵包的主要成分。","original_meaning":"成分","original_example":"Sugar is a common ingredient in desserts.","original_example_zh":"糖是甜點中常見的原料。"},{"source_id":3566,"word":"inheritance","meaning":"繼承","example":"The old violin was part of her inheritance from her grandmother.","example_zh":"那把老提琴是祖母留給她的一部分遺產。","original_meaning":"繼承","original_example":"He received a large inheritance.","original_example_zh":"他獲得了一筆龐大的遺產。"},{"source_id":3567,"word":"initiation","meaning":"啟動","example":"The initiation of the pond project brought all the volunteers together.","example_zh":"池塘計畫的啟動，讓所有志工聚集起來。","original_meaning":"啟動","original_example":"The ceremony marked his initiation.","original_example_zh":"這場儀式標誌著他的入會。"},{"source_id":3568,"word":"injunction","meaning":"禁令","example":"The court issued an injunction to stop work near the protected wetland.","example_zh":"法院發出禁令，停止保護濕地附近的工程。","original_meaning":"禁令","original_example":"The court issued an injunction.","original_example_zh":"法院頒布了禁制令。"},{"source_id":3569,"word":"innocence","meaning":"無辜","example":"The clear photograph proved the student's innocence.","example_zh":"清楚的照片證明那位學生是無辜的。","original_meaning":"無辜","original_example":"The man proved his innocence.","original_example_zh":"該男子證明了自己的清白。"},{"source_id":3570,"word":"innovative","meaning":"創新的","example":"The innovative design collected rainwater in the school's roof garden.","example_zh":"創新的設計能在學校屋頂花園收集雨水。","original_meaning":"創新的","original_example":"The company introduced innovative ideas.","original_example_zh":"該公司提出了創新構想。"},{"source_id":3571,"word":"inoculate","meaning":"接種","example":"The clinic planned to inoculate the volunteers during the health program.","example_zh":"診所計畫在健康活動中為志工接種疫苗。","original_meaning":"接種","original_example":"Doctors inoculate patients against disease.","original_example_zh":"醫生為患者接種疫苗以預防疾病。"},{"source_id":3572,"word":"insane","meaning":"瘋狂的","example":"We abandoned the insane plan to race through the storm.","example_zh":"我們放棄了在暴風雨中競速的瘋狂計畫。","original_meaning":"瘋狂的","original_example":"The behavior seemed insane.","original_example_zh":"那行為似乎瘋癲。"},{"source_id":3573,"word":"inscription","meaning":"銘文","example":"The old stone carried an inscription carved by hand.","example_zh":"老石頭上有手工雕刻的銘文。","original_meaning":"銘文","original_example":"The stone had an ancient inscription.","original_example_zh":"那塊石頭上有古文字銘文。"},{"source_id":3574,"word":"insignificant","meaning":"微不足道的","example":"A tiny stain was an insignificant flaw in the beautiful handmade bowl.","example_zh":"精美手工碗上的小色點，是個微不足道的瑕疵。","original_meaning":"微不足道的","original_example":"The difference was insignificant.","original_example_zh":"差異微乎其微。"},{"source_id":3575,"word":"insistence","meaning":"堅持","example":"At her insistence, we checked every helmet before the ride.","example_zh":"在她堅持下，我們騎車前檢查了每頂安全帽。","original_meaning":"堅持","original_example":"Her insistence finally convinced him.","original_example_zh":"她的堅持終於說服了他。"},{"source_id":3576,"word":"insolvent","meaning":"破產的；無力償債的","example":"The insolvent company could no longer repay its debts.","example_zh":"那家無力償債的公司，已無法還清債務。","original_meaning":"破產的","original_example":"The company became insolvent.","original_example_zh":"該公司宣告破產。"},{"source_id":3577,"word":"inspection","meaning":"檢查","example":"The safety inspection found a loose bolt on the bicycle.","example_zh":"安全檢查發現腳踏車上有顆鬆動螺栓。","original_meaning":"檢查","original_example":"The inspector conducted a full inspection.","original_example_zh":"檢查員進行了全面檢查。"},{"source_id":3578,"word":"instability","meaning":"不穩定","example":"The narrow base caused instability in the tall model tower.","example_zh":"狹窄底座讓高模型塔不穩定。","original_meaning":"不穩定","original_example":"Political instability affects markets.","original_example_zh":"政治動盪影響市場。"},{"source_id":3579,"word":"installment","meaning":"分期","example":"The musician paid for the violin in monthly installments.","example_zh":"音樂家用每月分期付款的方式買提琴。","original_meaning":"分期","original_example":"He paid for the car in installments.","original_example_zh":"他分期付款購買了那輛車。"},{"source_id":3580,"word":"institution","meaning":"機構","example":"The museum is an institution dedicated to preserving local history.","example_zh":"這座博物館是致力保存地方歷史的機構。","original_meaning":"機構","original_example":"The university is a respected institution.","original_example_zh":"這所大學是一所備受尊敬的機構。"},{"source_id":3581,"word":"instruction","meaning":"指示","example":"The clear instruction helped us fold the paper crane correctly.","example_zh":"清楚的指示幫助我們正確摺出紙鶴。","original_meaning":"指示","original_example":"Please follow the instructions carefully.","original_example_zh":"請仔細遵循指示。"},{"source_id":3582,"word":"insufficient","meaning":"不足的","example":"The small solar panel provided insufficient power for the large lamp.","example_zh":"小太陽能板提供的電力，不足以讓大燈亮起。","original_meaning":"不足的","original_example":"The supply is insufficient.","original_example_zh":"供應不足。"},{"source_id":3583,"word":"insulate","meaning":"隔離；隔熱；保溫","example":"We used thick wool to insulate the model house against the cold.","example_zh":"我們用厚羊毛替模型屋保溫，阻隔寒冷。","original_meaning":"隔離","original_example":"Insulate the wires for safety.","original_example_zh":"為了安全起見，請為電線做絕緣處理。"},{"source_id":3584,"word":"insurgent","meaning":"叛軍","example":"The history exhibit described an insurgent who later joined peace talks.","example_zh":"歷史展覽介紹一位後來參加和平談判的叛軍成員。","original_meaning":"叛軍","original_example":"The insurgents attacked the base.","original_example_zh":"叛軍襲擊了基地。"},{"source_id":3585,"word":"integral","meaning":"不可或缺的","example":"The water pump was an integral part of our classroom aquarium.","example_zh":"水泵是教室魚缸不可或缺的一部分。","original_meaning":"不可或缺的","original_example":"Trust is integral to relationships.","original_example_zh":"信任是人際關係不可或缺的要素。"},{"source_id":3586,"word":"intellectual","meaning":"智力的","example":"The difficult puzzle offered an intellectual challenge for the whole team.","example_zh":"這道難題為整個小組帶來智力挑戰。","original_meaning":"智力的","original_example":"He enjoys intellectual discussions.","original_example_zh":"他喜歡進行智性討論。"},{"source_id":3587,"word":"intelligence","meaning":"情報","example":"The naval museum displayed old maps used to gather intelligence.","example_zh":"海軍博物館展示過去用於蒐集情報的地圖。","original_meaning":"情報","original_example":"The agency gathered intelligence.","original_example_zh":"該機構蒐集了情報。"},{"source_id":3588,"word":"interaction","meaning":"互動","example":"The friendly interaction between the volunteers encouraged the new member.","example_zh":"志工之間友善的互動，鼓勵了新成員。","original_meaning":"互動","original_example":"Social interaction is important.","original_example_zh":"社交互動很重要。"},{"source_id":3589,"word":"intercept","meaning":"攔截","example":"Nora ran forward to intercept the pass.","example_zh":"諾拉跑向前，攔下對方的傳球。","original_meaning":"攔截","original_example":"The defense managed to intercept the pass.","original_example_zh":"防守方成功攔截了傳球。"},{"source_id":3590,"word":"interdependence","meaning":"相互依存","example":"The class studied the interdependence of bees and flowering plants.","example_zh":"班上研究蜜蜂與開花植物之間的相互依存。","original_meaning":"相互依存","original_example":"Countries rely on interdependence.","original_example_zh":"各國依賴相互依存。"},{"source_id":3591,"word":"interior","meaning":"內部","example":"The cabin's interior was warm and filled with handmade furniture.","example_zh":"木屋內部溫暖，擺滿手工家具。","original_meaning":"內部","original_example":"The interior of the house is modern.","original_example_zh":"屋內裝潢很現代。"},{"source_id":3592,"word":"intermediary","meaning":"中間人","example":"The teacher acted as an intermediary between the two clubs.","example_zh":"老師擔任兩個社團之間的中間人。","original_meaning":"中間人","original_example":"He acted as an intermediary in the deal.","original_example_zh":"他在這筆交易中擔任中間人。"},{"source_id":3593,"word":"interpretation","meaning":"解讀","example":"Her interpretation of the poem focused on hope after hardship.","example_zh":"她對詩的解讀，著重於困境過後的希望。","original_meaning":"解讀","original_example":"Different interpretations are possible.","original_example_zh":"可能有不同的解讀。"},{"source_id":3594,"word":"interrogate","meaning":"審問","example":"The detective began to interrogate the suspect about the missing painting.","example_zh":"偵探開始詢問嫌疑人關於失蹤畫作的事。","original_meaning":"審問","original_example":"The police will interrogate the suspect.","original_example_zh":"警方將訊問嫌犯。"},{"source_id":3595,"word":"intersection","meaning":"十字路口；交叉口","example":"The crossing guard helped students cross the busy intersection.","example_zh":"導護人員幫助學生穿越繁忙交叉路口。","original_meaning":"十字路口；交叉口","original_example":"A police officer directed traffic at the intersection when the lights failed.","original_example_zh":"號誌故障時，警察在十字路口指揮交通。"},{"source_id":3596,"word":"intervention","meaning":"干預","example":"The counselor's intervention helped the classmates resolve their disagreement.","example_zh":"輔導老師的介入，幫助同學化解歧見。","original_meaning":"干預","original_example":"International intervention was required.","original_example_zh":"需要國際介入。"},{"source_id":3597,"word":"intimidate","meaning":"恐嚇","example":"The player tried to intimidate his opponent, but the referee intervened.","example_zh":"球員試圖恐嚇對手，但裁判立即介入。","original_meaning":"恐嚇","original_example":"He tried to intimidate the witness.","original_example_zh":"他試圖威嚇證人。"},{"source_id":3598,"word":"intolerance","meaning":"不容忍；偏狹","example":"The class discussed how intolerance can exclude people with different opinions.","example_zh":"班上討論偏狹如何排斥持不同意見的人。","original_meaning":"不容忍","original_example":"Religious intolerance causes conflict.","original_example_zh":"宗教不寬容導致衝突。"},{"source_id":3599,"word":"intrigue","meaning":"陰謀","example":"The detective story centered on a palace intrigue.","example_zh":"偵探故事圍繞一場宮廷陰謀展開。","original_meaning":"陰謀","original_example":"The story is full of intrigue.","original_example_zh":"這個故事充滿了陰謀詭計。"},{"source_id":3600,"word":"intrusion","meaning":"侵入","example":"The fence protected the nesting area from human intrusion.","example_zh":"柵欄保護築巢區，避免人類闖入。","original_meaning":"侵入","original_example":"The system detected an intrusion.","original_example_zh":"系統偵測到入侵。"},{"source_id":3601,"word":"intuition","meaning":"直覺","example":"Her intuition led her to check the loose wheel before the trip.","example_zh":"直覺讓她在出發前檢查那個鬆動輪子。","original_meaning":"直覺","original_example":"Trust your intuition.","original_example_zh":"相信你的直覺。"},{"source_id":3602,"word":"inverse","meaning":"相反的","example":"The second row showed the blocks in inverse order.","example_zh":"第二排積木以相反順序排列。","original_meaning":"相反的","original_example":"There is an inverse relationship between the two.","original_example_zh":"兩者之間存在反比關係。"},{"source_id":3603,"word":"irrigation","meaning":"灌溉","example":"The irrigation system carried rainwater to every garden bed.","example_zh":"灌溉系統把雨水送到每一塊菜圃。","original_meaning":"灌溉","original_example":"Irrigation helps crops grow.","original_example_zh":"灌溉有助作物生長。"},{"source_id":3604,"word":"isolationism","meaning":"孤立主義","example":"The history lesson examined isolationism and reluctance to join foreign alliances.","example_zh":"歷史課探討孤立主義，以及不願加入國際同盟的態度。","original_meaning":"孤立主義","original_example":"Isolationism limits international cooperation.","original_example_zh":"孤立主義限制了國際合作。"},{"source_id":3605,"word":"itinerary","meaning":"行程表；旅行計畫","example":"Our itinerary included the museum, the old harbor, and a quiet garden.","example_zh":"我們的行程包括博物館、老港口與安靜花園。","original_meaning":"行程表；旅行計畫","original_example":"Our itinerary leaves one free afternoon to explore the old town.","original_example_zh":"我們的行程留了一個自由活動的下午探索老城區。"},{"source_id":3606,"word":"jargon","meaning":"術語","example":"The technician explained the jargon in simple words for the students.","example_zh":"技師用簡單的話，向學生解釋專業術語。","original_meaning":"術語","original_example":"The lecture was full of technical jargon.","original_example_zh":"那場演講充滿了專業術語。"},{"source_id":3607,"word":"journalism","meaning":"新聞業","example":"The students explored journalism by interviewing people for the school paper.","example_zh":"學生透過為校刊採訪人物，探索新聞工作。","original_meaning":"新聞業","original_example":"She works in journalism.","original_example_zh":"她從事新聞工作。"},{"source_id":3608,"word":"jubilee","meaning":"慶典","example":"The school celebrated its jubilee with a concert and a reunion.","example_zh":"學校以音樂會與校友聚會慶祝週年慶典。","original_meaning":"慶典","original_example":"The country celebrated its jubilee.","original_example_zh":"該國慶祝了其週年紀念。"},{"source_id":3609,"word":"judiciary","meaning":"司法機構","example":"The museum explained the judiciary's role in applying the law.","example_zh":"博物館說明司法機構適用法律的角色。","original_meaning":"司法機構","original_example":"The judge made a fair judgment.","original_example_zh":"法官做出了公正的判決。"},{"source_id":3610,"word":"justification","meaning":"正當理由","example":"The cracked beam provided justification for closing the footbridge.","example_zh":"橫梁裂縫提供了關閉人行橋的正當理由。","original_meaning":"正當理由","original_example":"Justice must be served equally.","original_example_zh":"正義必須平等地伸張。"},{"source_id":3611,"word":"juvenile","meaning":"少年的；幼年的","example":"The juvenile bird waited in the nest while its parents gathered food.","example_zh":"幼鳥待在巢裡，等待親鳥覓食。","original_meaning":"少年的","original_example":"He works as a journalist.","original_example_zh":"他是一名記者。"},{"source_id":3612,"word":"keynote","meaning":"主題；主題演說","example":"The keynote set a hopeful tone for the science festival.","example_zh":"主題演說為科學節帶來充滿希望的氣氛。","original_meaning":"主題","original_example":"The project required careful justification.","original_example_zh":"該計畫需要仔細的論證。"},{"source_id":3613,"word":"kidnap","meaning":"綁架","example":"The police stopped a plan to kidnap the diplomat.","example_zh":"警方阻止了一場綁架外交官的計畫。","original_meaning":"綁架","original_example":"The company made a large profit this quarter.","original_example_zh":"該公司本季獲利豐厚。"},{"source_id":3614,"word":"kinetic","meaning":"動力的；動能的","example":"The moving cart had kinetic energy as it rolled down the ramp.","example_zh":"推車沿斜坡滾下時，具有動能。","original_meaning":"動力的","original_example":"The system crashed due to a kernel error.","original_example_zh":"系統因核心錯誤而當機。"},{"source_id":3615,"word":"labyrinth","meaning":"迷宮","example":"The garden labyrinth led us to a small fountain at its center.","example_zh":"花園迷宮引領我們來到中央的小噴泉。","original_meaning":"迷宮","original_example":"The king ruled the land wisely.","original_example_zh":"國王以明智的方式統治這片土地。"},{"source_id":3616,"word":"landscape","meaning":"風景","example":"The painter captured the peaceful landscape around the lake.","example_zh":"畫家捕捉湖畔寧靜的風景。","original_meaning":"風景","original_example":"Kindness is appreciated everywhere.","original_example_zh":"善良在任何地方都受到讚賞。"},{"source_id":3617,"word":"lateral","meaning":"側面的","example":"The crab moved in a lateral direction across the sand.","example_zh":"螃蟹側向走過沙地。","original_meaning":"側面的","original_example":"Knowledge is the key to success.","original_example_zh":"知識是成功的關鍵。"},{"source_id":3618,"word":"latitude","meaning":"緯度","example":"The globe showed latitude as circles parallel to the equator.","example_zh":"地球儀用平行赤道的圓圈表示緯度。","original_meaning":"緯度","original_example":"Labor costs are increasing.","original_example_zh":"勞動力成本正在上升。"},{"source_id":3619,"word":"launder","meaning":"洗錢","example":"The court examined evidence that the company had tried to launder money.","example_zh":"法院檢視公司企圖洗錢的證據。","original_meaning":"洗錢","original_example":"The laboratory is well equipped.","original_example_zh":"實驗室設備齊全。"},{"source_id":3620,"word":"lawsuit","meaning":"訴訟","example":"The neighbors settled the lawsuit after reaching a fair agreement.","example_zh":"鄰居達成公平協議後，解決了訴訟。","original_meaning":"訴訟","original_example":"Language reflects culture.","original_example_zh":"語言反映文化。"},{"source_id":3621,"word":"legislature","meaning":"立法機關","example":"The legislature debated a proposal to protect the old forest.","example_zh":"立法機關辯論保護古老森林的提案。","original_meaning":"立法機關","original_example":"The laptop battery lasted all day.","original_example_zh":"筆電電池續航力一整天。"},{"source_id":3622,"word":"legitimacy","meaning":"合法性","example":"The official seal helped confirm the document's legitimacy.","example_zh":"官方印章有助於確認文件的合法性。","original_meaning":"合法性","original_example":"The lawyer prepared the case carefully.","original_example_zh":"律師仔細準備了案件。"},{"source_id":3623,"word":"lethargy","meaning":"昏睡；倦怠","example":"After the long journey, a feeling of lethargy made him move slowly.","example_zh":"漫長旅程後，他倦怠得動作緩慢。","original_meaning":"昏睡","original_example":"Leadership requires responsibility.","original_example_zh":"領導力需要責任感。"},{"source_id":3624,"word":"levy","meaning":"徵收","example":"The imaginary town voted to levy a small tax for its new bridge.","example_zh":"虛構城鎮投票決定徵收小額稅款，興建新橋。","original_meaning":"徵收","original_example":"The lecture was informative.","original_example_zh":"這場講座內容豐富。"},{"source_id":3625,"word":"lexicon","meaning":"詞彙","example":"The class created a lexicon of words related to the school garden.","example_zh":"班上整理一份與校園花園相關的詞彙集。","original_meaning":"詞彙","original_example":"He made a legal claim.","original_example_zh":"他提出了法律索賠。"},{"source_id":3626,"word":"liability","meaning":"責任","example":"Anyone borrowing the camera accepted liability for careless damage.","example_zh":"借相機的人同意為疏忽造成的損壞負責。","original_meaning":"責任","original_example":"The library is open to the public.","original_example_zh":"圖書館對公眾開放。"},{"source_id":3627,"word":"liberation","meaning":"解放","example":"The story celebrated the villagers' liberation from an unjust ruler.","example_zh":"故事慶祝村民擺脫不公統治者、獲得解放。","original_meaning":"解放","original_example":"Light travels faster than sound.","original_example_zh":"光速快於聲速。"},{"source_id":3628,"word":"lieutenant","meaning":"中尉","example":"The army lieutenant led the rescue team into the flooded village.","example_zh":"陸軍中尉帶領救援隊進入淹水村落。","original_meaning":"中尉","original_example":"The limit was reached quickly.","original_example_zh":"很快就達到極限。"},{"source_id":3629,"word":"limitation","meaning":"限制","example":"The battery's short life was a limitation of our model robot.","example_zh":"電池續航短，是我們模型機器人的一項限制。","original_meaning":"限制","original_example":"The machine operates efficiently.","original_example_zh":"機器運作高效。"},{"source_id":3630,"word":"lineage","meaning":"血統","example":"The old portraits helped the family trace its lineage.","example_zh":"老肖像幫助這家人追溯家族血統。","original_meaning":"血統","original_example":"Maintenance is required regularly.","original_example_zh":"需要定期維護。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-illuminate-01-v1","level":"senior","word":"illuminate","sort_order":1,"sense":"照亮","alt_zh":"高中生在木屋桌前用小燈照亮無字地圖，周圍光線柔暗。","example":"The small lamp helped illuminate the map inside the dark cabin.","example_zh":"小燈幫忙照亮昏暗木屋裡的地圖。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/illuminate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-illiterate-01-v1","level":"senior","word":"illiterate","sort_order":1,"sense":"文盲的；不識字的","alt_zh":"圖書館志工與成年學習者平等坐在桌前，溫和陪讀圖文書，文字不可辨識。","example":"The volunteer patiently helped an illiterate adult learn to read.","example_zh":"志工耐心幫助不識字的成年人學習閱讀。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/illiterate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-immerse-01-v1","level":"senior","word":"immerse","sort_order":1,"sense":"沈浸","alt_zh":"高中樂團在溫暖教室專注演奏，神情投入、忘卻周遭。","example":"We could immerse ourselves in music during the quiet rehearsal.","example_zh":"安靜排練時，我們能沉浸在音樂裡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/immerse-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-immigration-01-v1","level":"senior","word":"immigration","sort_order":1,"sense":"移民","alt_zh":"高中生參觀博物館，觀看家庭帶行李抵達舊港口的歷史模型。","example":"The museum traced the history of immigration to the port city.","example_zh":"博物館追溯移民來到這座港都的歷史。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/immigration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-immortal-01-v1","level":"senior","word":"immortal","sort_order":1,"sense":"不朽的","alt_zh":"家中長者與高中孩子一起讀古老故事書，旁邊有祖先也讀過同一本書的老照片。","example":"The poet's immortal stories were read by many generations.","example_zh":"那位詩人不朽的故事，流傳給許多世代閱讀。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/immortal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-immunity-01-v1","level":"senior","word":"immunity","sort_order":1,"sense":"免疫","alt_zh":"老師與高中生觀察透明人體教學模型，免疫細胞模型保護身體、阻擋病菌模型。","example":"The science model showed how immunity helps the body resist disease.","example_zh":"科學模型展示免疫如何幫助身體抵抗疾病。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/immunity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-impartial-01-v1","level":"senior","word":"impartial","sort_order":1,"sense":"公正的","alt_zh":"成年科學競賽評審平等查看兩隊高中生的作品，專注聽雙方說明。","example":"The impartial judge listened carefully to both teams.","example_zh":"公正的評審仔細聆聽兩隊的說明。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/impartial-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-impasse-01-v1","level":"senior","word":"impasse","sort_order":1,"sense":"僵局","alt_zh":"兩組高中社團代表在排練室外各持安排表，困惑對坐、尚未達成共識。","example":"The clubs reached an impasse over how to share the rehearsal room.","example_zh":"兩個社團在如何共用排練室的問題上陷入僵局。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/impasse-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-impeach-01-v1","level":"senior","word":"impeach","sort_order":1,"sense":"彈劾","alt_zh":"高中生在歷史課看虛構議會模型，成年議員正式表決對官員提出指控，無黨徽。","example":"The history class learned why lawmakers voted to impeach an official.","example_zh":"歷史課學習議員為何投票彈劾一位官員。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/impeach-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-impediment-01-v1","level":"senior","word":"impediment","sort_order":1,"sense":"障礙","alt_zh":"高中生在安全坡道停下裝物資推車，前方一根倒枝擋住道路。","example":"The fallen branch was an impediment to carrying the cart uphill.","example_zh":"倒枝妨礙我們把推車往坡上推。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/impediment-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-imperialism-01-v1","level":"senior","word":"imperialism","sort_order":1,"sense":"帝國主義","alt_zh":"高中生在博物館看虛構歷史地圖與城邦模型，老師客觀解說帝國對外擴張。","example":"The exhibit examined how imperialism expanded control over distant territories.","example_zh":"展覽探討帝國主義如何把控制擴展到遠方領土。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/imperialism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-impetus-01-v1","level":"senior","word":"impetus","sort_order":1,"sense":"動力","alt_zh":"高中樂團在成功演出後受到鼓舞，開心拿樂器準備下一次練習。","example":"The successful first concert gave the orchestra fresh impetus.","example_zh":"第一場音樂會成功，給管弦樂團帶來新的動力。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/impetus-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-implausible-01-v1","level":"senior","word":"implausible","sort_order":1,"sense":"不合理的","alt_zh":"高中生懷疑地比較手掌大小的玩具吊車與沉重腳踏車，老師引導思考。","example":"The claim that the tiny toy could lift a bicycle seemed implausible.","example_zh":"說小玩具能舉起腳踏車，聽起來不太合理。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/implausible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-imposition-01-v1","level":"senior","word":"imposition","